UPDATE products
name = #{name}, description = #{description}, category_id = #{categoryId}, price = #{price}, stock = #{stock}, sales = #{sales}, image_url = #{imageUrl}, images = #{images}, status = #{status},
WHERE id = #{id}

UPDATE products
   SET stock = stock - #{qty},
       sales = sales + #{qty}
 WHERE id = #{id} AND stock >= #{qty}

UPDATE products
   SET stock = stock + #{qty},
       sales = sales - #{qty}
 WHERE id = #{id}
